/**
 * @name Command injection in edit_files via filename
 * @description Filenames passed to edit_files can contain shell metacharacters that bypass quoting
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-edit-files
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to edit_files or edit functions
    exists(Function f |
      f.getName() in ["edit_files", "edit"] and
      source.asExpr().(Name).getId() = f.getAnArg().asName().getId()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // subprocess.Popen with shell=True
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user-controlled filename"

/**
 * @name Directory traversal via path manipulation
 * @description Path operations without proper validation can lead to directory traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-file-access
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that might contain paths
    exists(Function f, Parameter p |
      p = f.getAnArg() and
      (
        p.asName().getId().toLowerCase().matches("%path%") or
        p.asName().getId().toLowerCase().matches("%file%") or
        p.asName().getId().toLowerCase().matches("%dir%")
      ) and
      source.asExpr().(Name).getId() = p.asName().getId()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user input"
